<?php
declare(strict_types=1);

require_once __DIR__ . '/../lib/bbs_phase1.php';

function bbs_inspector_actor(array $user): string { return trim((string) ($user['id'] ?? $user['EmployeeID'] ?? '')); }
function bbs_inspector_admin(array $user): bool { return strcasecmp((string) ($user['role'] ?? $user['Role'] ?? ''), 'Admin') === 0; }
function bbs_inspector_clean($value, int $max = 255): string { return mb_substr(trim((string) $value), 0, $max); }
function bbs_inspector_bool($value, bool $fallback = true): bool { if ($value === null) return $fallback; return !($value === false || $value === 0 || $value === '0' || strtolower((string) $value) === 'false'); }
function bbs_inspector_today(): string { return (new DateTimeImmutable('now', new DateTimeZone('Asia/Bangkok')))->format('Y-m-d'); }
function bbs_inspector_statuses(): array { return ['Active', 'Suspended', 'Ended']; }
function bbs_inspector_enabled(): bool { $row=db_row("SELECT SettingValue FROM BBS_Settings WHERE SettingKey='inspector_team_management_enabled' LIMIT 1"); return (string)($row['SettingValue']??'0')==='1'; }

function bbs_inspector_employee(string $employeeId): ?array {
    return db_row("SELECT e.EmployeeID,e.EmployeeName,e.Department,e.Unit,e.Position,e.Role,d.id DepartmentID,u.id SafetyUnitID,m.BBSLevel FROM employees e LEFT JOIN master_departments d ON LOWER(TRIM(d.Name))=LOWER(TRIM(e.Department)) LEFT JOIN master_safetyunits u ON u.department_id=d.id AND LOWER(TRIM(u.name))=LOWER(TRIM(e.Unit)) LEFT JOIN master_positions p ON LOWER(TRIM(p.Name))=LOWER(TRIM(e.Position)) LEFT JOIN BBS_Position_Level_Mappings m ON m.PositionID=p.id AND m.IsActive=1 WHERE e.EmployeeID=? LIMIT 1",[$employeeId]);
}

function bbs_inspector_enrollment(int $id, bool $lock=false): ?array {
    return db_row("SELECT x.*,e.EmployeeName,e.Department,e.Unit,e.Position,d.Name DepartmentName,u.name SafetyUnitName FROM BBS_Inspector_Enrollments x JOIN employees e ON e.EmployeeID=x.InspectorEmployeeID JOIN master_departments d ON d.id=x.DepartmentID JOIN master_safetyunits u ON u.id=x.SafetyUnitID WHERE x.id=? LIMIT 1".($lock?' FOR UPDATE':''),[$id]);
}

function bbs_inspector_effective(array $row,string $asOf): bool {
    return (int)($row['IsActive']??0)===1&&($row['Status']??'')==='Active'&&substr((string)$row['EffectiveFrom'],0,10)<=$asOf&&(empty($row['EffectiveTo'])||substr((string)$row['EffectiveTo'],0,10)>=$asOf);
}

function bbs_inspector_access(array $user,array $enrollment,string $asOf): array {
    if(bbs_inspector_admin($user))return['actorMode'=>'Admin'];
    if((string)$enrollment['InspectorEmployeeID']!==bbs_inspector_actor($user))return['error'=>[403,'This inspector enrollment belongs to another employee.']];
    if((int)$enrollment['AllowSelfManage']!==1)return['error'=>[403,'Admin has locked self-service team management for this inspector.']];
    if(!bbs_inspector_effective($enrollment,$asOf))return['error'=>[409,'The inspector enrollment is not Active for today.']];
    return['actorMode'=>'Self'];
}

function bbs_inspector_team_payload(array $enrollment,string $asOf): array {
    $monthStart=substr($asOf,0,7).'-01';$monthEnd=(new DateTimeImmutable($monthStart,new DateTimeZone('UTC')))->modify('+1 month')->format('Y-m-d');
    $team=db_rows("SELECT a.id AssignmentID,a.EffectiveFrom,a.EffectiveTo,a.AssignmentType,a.Reason,e.EmployeeID,e.EmployeeName,e.Department,e.Unit,e.Position,COUNT(o.id) SubmittedCount,MAX(o.SubmittedAt) LastObservedAt FROM BBS_Hierarchy_Assignments a JOIN employees e ON e.EmployeeID=a.MemberEmployeeID LEFT JOIN BBS_Observations o ON o.ObserverEmployeeID=a.SupervisorEmployeeID AND o.ObservedEmployeeID=a.MemberEmployeeID AND o.Status='Submitted' AND o.ObservationDate>=? AND o.ObservationDate<? WHERE a.SupervisorEmployeeID=? AND a.DepartmentID=? AND a.SafetyUnitID=? AND a.IsActive=1 AND a.EffectiveFrom<=? AND COALESCE(a.EffectiveTo,'9999-12-31')>=? GROUP BY a.id,e.EmployeeID,e.EmployeeName,e.Department,e.Unit,e.Position ORDER BY e.EmployeeName",[$monthStart,$monthEnd,$enrollment['InspectorEmployeeID'],$enrollment['DepartmentID'],$enrollment['SafetyUnitID'],$asOf,$asOf]);
    $available=db_rows("SELECT e.EmployeeID,e.EmployeeName,e.Department,e.Unit,e.Position,own.SupervisorEmployeeID CurrentSupervisorID,s.EmployeeName CurrentSupervisorName FROM employees e JOIN master_positions p ON LOWER(TRIM(p.Name))=LOWER(TRIM(e.Position)) JOIN BBS_Position_Level_Mappings m ON m.PositionID=p.id AND m.IsActive=1 AND m.BBSLevel='Operator' JOIN master_departments d ON LOWER(TRIM(d.Name))=LOWER(TRIM(e.Department)) AND d.id=? JOIN master_safetyunits u ON u.department_id=d.id AND LOWER(TRIM(u.name))=LOWER(TRIM(e.Unit)) AND u.id=? LEFT JOIN BBS_Employee_Eligibility elig ON elig.id=(SELECT ee.id FROM BBS_Employee_Eligibility ee WHERE ee.EmployeeID=e.EmployeeID AND ee.IsActive=1 AND ee.EffectiveFrom<=? AND COALESCE(ee.EffectiveTo,'9999-12-31')>=? ORDER BY ee.EffectiveFrom DESC,ee.id DESC LIMIT 1) LEFT JOIN BBS_Hierarchy_Assignments own ON own.id=(SELECT h.id FROM BBS_Hierarchy_Assignments h WHERE h.MemberEmployeeID=e.EmployeeID AND h.IsActive=1 AND h.EffectiveFrom<=? AND COALESCE(h.EffectiveTo,'9999-12-31')>=? ORDER BY h.id DESC LIMIT 1) LEFT JOIN employees s ON s.EmployeeID=own.SupervisorEmployeeID WHERE COALESCE(elig.Eligibility,'active')='active' ORDER BY e.EmployeeName",[$enrollment['DepartmentID'],$enrollment['SafetyUnitID'],$asOf,$asOf,$asOf,$asOf]);
    $observed=[];foreach($team as$row)if((int)($row['SubmittedCount']??0)>0)$observed[(string)$row['EmployeeID']]=true;$total=count($team);
    return['team'=>$team,'available'=>$available,'coverage'=>['observed'=>count($observed),'total'=>$total,'percentage'=>$total?round(count($observed)*10000/$total)/100:0]];
}

function bbs_inspector_validate(array $body,?int $excludeId=null): array {
    $inspectorId=bbs_inspector_clean($body['inspectorEmployeeId']??'',20);$departmentId=bbs_phase1_positive_int($body['departmentId']??null);$unitId=bbs_phase1_positive_int($body['safetyUnitId']??null);$status=in_array($body['status']??'',bbs_inspector_statuses(),true)?(string)$body['status']:'Active';$range=bbs_phase1_validate_range($body['effectiveFrom']??null,$body['effectiveTo']??null);
    if($inspectorId===''||!$departmentId||!$unitId||empty($range['ok']))return['error'=>[400,$range['message']??'Inspector, Department, Safety Unit and effective dates are required.']];
    $inspector=bbs_inspector_employee($inspectorId);if(!$inspector)return['error'=>[404,'Inspector employee was not found.']];if(($inspector['BBSLevel']??'')!=='Group Leader')return['error'=>[400,'Only an active Group Leader mapping can be appointed as an inspector.']];if((int)$inspector['DepartmentID']!==$departmentId||(int)$inspector['SafetyUnitID']!==$unitId)return['error'=>[400,'Inspector must belong to the selected Department and Safety Unit.']];
    $sql="SELECT id FROM BBS_Inspector_Enrollments WHERE InspectorEmployeeID=? AND IsActive=1 AND EffectiveFrom<=? AND COALESCE(EffectiveTo,'9999-12-31')>=?";$params=[$inspectorId,$range['to']?:'9999-12-31',$range['from']];if($excludeId){$sql.=' AND id<>?';$params[]=$excludeId;}$sql.=' LIMIT 1 FOR UPDATE';if(db_row($sql,$params))return['error'=>[409,'This Group Leader already has an overlapping inspector enrollment.']];
    return['inspectorId'=>$inspectorId,'departmentId'=>$departmentId,'safetyUnitId'=>$unitId,'status'=>$status,'range'=>$range,'kpiRequired'=>bbs_inspector_bool($body['kpiRequired']??null),'allowSelfManage'=>bbs_inspector_bool($body['allowSelfManage']??null),'reason'=>bbs_inspector_clean($body['reason']??'')?:null];
}

function handle_bbs_inspector_routes(string $method,string $path): bool {
    if(strpos($path,'/bbs/inspectors')!==0&&strpos($path,'/bbs/admin/inspectors')!==0)return false;
    $user=require_user();$actor=bbs_inspector_actor($user);
    $requiresEnabledFeature = $method !== 'GET'
        || ($path !== '/bbs/inspectors/me' && $path !== '/bbs/admin/inspectors');
    if($requiresEnabledFeature&&!bbs_inspector_enabled())json_response(['success'=>false,'code'=>'BBS_INSPECTOR_FEATURE_DISABLED','message'=>'BBS inspector team management is currently disabled.'],503);
    if($method==='GET'&&$path==='/bbs/inspectors/me'){
        $asOf=bbs_phase1_iso_date($_GET['asOf']??bbs_inspector_today(),true);if(!$asOf)json_response(['success'=>false,'message'=>'asOf must be a valid YYYY-MM-DD date.'],400);if(!bbs_inspector_enabled())json_response(['success'=>true,'data'=>['enabled'=>false,'enrollment'=>null,'team'=>[],'available'=>[],'coverage'=>['observed'=>0,'total'=>0,'percentage'=>0]]]);
        $enrollment=db_row("SELECT x.*,d.Name DepartmentName,u.name SafetyUnitName FROM BBS_Inspector_Enrollments x JOIN master_departments d ON d.id=x.DepartmentID JOIN master_safetyunits u ON u.id=x.SafetyUnitID WHERE x.InspectorEmployeeID=? AND x.IsActive=1 AND x.EffectiveFrom<=? AND COALESCE(x.EffectiveTo,'9999-12-31')>=? ORDER BY (x.Status='Active') DESC,x.EffectiveFrom DESC,x.id DESC LIMIT 1",[$actor,$asOf,$asOf]);if(!$enrollment)json_response(['success'=>true,'data'=>['enabled'=>true,'enrollment'=>null,'team'=>[],'available'=>[],'coverage'=>['observed'=>0,'total'=>0,'percentage'=>0]]]);$payload=bbs_inspector_team_payload($enrollment,$asOf);json_response(['success'=>true,'data'=>array_merge(['enabled'=>true,'enrollment'=>$enrollment,'canSelfManage'=>bbs_inspector_effective($enrollment,$asOf)&&(int)$enrollment['AllowSelfManage']===1],$payload)]);
    }
    if($method==='GET'&&$path==='/bbs/admin/inspectors'){
        require_admin();$asOf=bbs_phase1_iso_date($_GET['asOf']??bbs_inspector_today(),true);if(!$asOf)json_response(['success'=>false,'message'=>'asOf must be a valid YYYY-MM-DD date.'],400);
        $enrollments=db_rows("SELECT x.*,e.EmployeeName,e.Department,e.Unit,e.Position,d.Name DepartmentName,u.name SafetyUnitName,(SELECT COUNT(*) FROM BBS_Hierarchy_Assignments h WHERE h.SupervisorEmployeeID=x.InspectorEmployeeID AND h.DepartmentID=x.DepartmentID AND h.SafetyUnitID=x.SafetyUnitID AND h.IsActive=1 AND h.EffectiveFrom<=? AND COALESCE(h.EffectiveTo,'9999-12-31')>=?) TeamCount FROM BBS_Inspector_Enrollments x JOIN employees e ON e.EmployeeID=x.InspectorEmployeeID JOIN master_departments d ON d.id=x.DepartmentID JOIN master_safetyunits u ON u.id=x.SafetyUnitID ORDER BY x.IsActive DESC,(x.Status='Active') DESC,x.EffectiveFrom DESC,x.id DESC",[$asOf,$asOf]);
        $candidates=db_rows("SELECT e.EmployeeID,e.EmployeeName,e.Department,e.Unit,e.Position,d.id DepartmentID,u.id SafetyUnitID FROM employees e JOIN master_positions p ON LOWER(TRIM(p.Name))=LOWER(TRIM(e.Position)) JOIN BBS_Position_Level_Mappings m ON m.PositionID=p.id AND m.IsActive=1 AND m.BBSLevel='Group Leader' LEFT JOIN master_departments d ON LOWER(TRIM(d.Name))=LOWER(TRIM(e.Department)) LEFT JOIN master_safetyunits u ON u.department_id=d.id AND LOWER(TRIM(u.name))=LOWER(TRIM(e.Unit)) ORDER BY e.Department,e.Unit,e.EmployeeName");
        json_response(['success'=>true,'data'=>['enabled'=>bbs_inspector_enabled(),'statuses'=>bbs_inspector_statuses(),'enrollments'=>$enrollments,'candidates'=>$candidates,'departments'=>db_rows('SELECT id,Name FROM master_departments ORDER BY Name'),'units'=>db_rows('SELECT id,name,department_id FROM master_safetyunits ORDER BY department_id,sort_order,name')]]);
    }
    if($method==='POST'&&$path==='/bbs/admin/inspectors'){
        if(!bbs_inspector_enabled())json_response(['success'=>false,'code'=>'BBS_INSPECTOR_FEATURE_DISABLED','message'=>'BBS inspector team management is currently disabled.'],503);
        $admin=require_admin();$body=json_body();$pdo=db();$pdo->beginTransaction();try{$checked=bbs_inspector_validate($body);if(isset($checked['error'])){$pdo->rollBack();json_response(['success'=>false,'message'=>$checked['error'][1]],$checked['error'][0]);}$stmt=$pdo->prepare('INSERT INTO BBS_Inspector_Enrollments(InspectorEmployeeID,DepartmentID,SafetyUnitID,Status,KpiRequired,AllowSelfManage,EffectiveFrom,EffectiveTo,IsActive,Reason,CreatedBy,UpdatedBy) VALUES(?,?,?,?,?,?,?,?,1,?,?,?)');$stmt->execute([$checked['inspectorId'],$checked['departmentId'],$checked['safetyUnitId'],$checked['status'],$checked['kpiRequired']?1:0,$checked['allowSelfManage']?1:0,$checked['range']['from'],$checked['range']['to'],$checked['reason'],$actor,$actor]);$id=(int)$pdo->lastInsertId();$pdo->commit();bbs_phase1_audit($admin,'BBS_INSPECTOR_ENROLL','BBS_Inspector_Enrollment',(string)$id,$checked['inspectorId'].'; scope='.$checked['departmentId'].':'.$checked['safetyUnitId']);json_response(['success'=>true,'data'=>['id'=>$id],'message'=>'BBS inspector appointed.'],201);}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}
    }
    $update=route_params($path,'/bbs/admin/inspectors/:id');if($method==='PUT'&&$update!==null){$admin=require_admin();$id=bbs_phase1_positive_int($update['id']);$body=json_body();$rowVersion=bbs_phase1_positive_int($body['rowVersion']??null);if(!$id||!$rowVersion)json_response(['success'=>false,'message'=>'Valid enrollment ID and RowVersion are required.'],400);$pdo=db();$pdo->beginTransaction();try{$existing=bbs_inspector_enrollment($id,true);if(!$existing){$pdo->rollBack();json_response(['success'=>false,'message'=>'Inspector enrollment was not found.'],404);}if((int)$existing['RowVersion']!==$rowVersion){$pdo->rollBack();json_response(['success'=>false,'code'=>'VERSION_CONFLICT','message'=>'Inspector enrollment changed. Reload before saving.'],409);}$checked=bbs_inspector_validate($body,$id);if(isset($checked['error'])){$pdo->rollBack();json_response(['success'=>false,'message'=>$checked['error'][1]],$checked['error'][0]);}db_execute('UPDATE BBS_Inspector_Enrollments SET InspectorEmployeeID=?,DepartmentID=?,SafetyUnitID=?,Status=?,KpiRequired=?,AllowSelfManage=?,EffectiveFrom=?,EffectiveTo=?,IsActive=?,Reason=?,RowVersion=RowVersion+1,UpdatedBy=? WHERE id=?',[$checked['inspectorId'],$checked['departmentId'],$checked['safetyUnitId'],$checked['status'],$checked['kpiRequired']?1:0,$checked['allowSelfManage']?1:0,$checked['range']['from'],$checked['range']['to'],bbs_inspector_bool($body['isActive']??null)?1:0,$checked['reason'],$actor,$id]);$pdo->commit();bbs_phase1_audit($admin,'BBS_INSPECTOR_UPDATE','BBS_Inspector_Enrollment',(string)$id,$checked['inspectorId'].'; status='.$checked['status']);json_response(['success'=>true,'message'=>'BBS inspector enrollment saved.']);}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}}
    $team=route_params($path,'/bbs/inspectors/:id/team');if($method==='GET'&&$team!==null){$id=bbs_phase1_positive_int($team['id']);$asOf=bbs_phase1_iso_date($_GET['asOf']??bbs_inspector_today(),true);if(!$id||!$asOf)json_response(['success'=>false,'message'=>'Valid enrollment ID and asOf are required.'],400);$enrollment=bbs_inspector_enrollment($id);if(!$enrollment)json_response(['success'=>false,'message'=>'Inspector enrollment was not found.'],404);$access=bbs_inspector_access($user,$enrollment,$asOf);if(isset($access['error']))json_response(['success'=>false,'message'=>$access['error'][1]],$access['error'][0]);json_response(['success'=>true,'data'=>array_merge(['enrollment'=>$enrollment,'canSelfManage'=>$access['actorMode']==='Admin'||(int)$enrollment['AllowSelfManage']===1],bbs_inspector_team_payload($enrollment,$asOf))]);}
    if($method==='POST'&&$team!==null){$id=bbs_phase1_positive_int($team['id']);$body=json_body();$memberId=bbs_inspector_clean($body['memberEmployeeId']??'',20);$asOf=bbs_phase1_iso_date($body['effectiveFrom']??bbs_inspector_today(),true);if(!$id||$memberId===''||!$asOf)json_response(['success'=>false,'message'=>'Enrollment, member and effective date are required.'],400);$pdo=db();$pdo->beginTransaction();try{$enrollment=bbs_inspector_enrollment($id,true);if(!$enrollment){$pdo->rollBack();json_response(['success'=>false,'message'=>'Inspector enrollment was not found.'],404);}$access=bbs_inspector_access($user,$enrollment,bbs_inspector_today());if(isset($access['error'])){$pdo->rollBack();json_response(['success'=>false,'message'=>$access['error'][1]],$access['error'][0]);}if($asOf<substr((string)$enrollment['EffectiveFrom'],0,10)||(!empty($enrollment['EffectiveTo'])&&$asOf>substr((string)$enrollment['EffectiveTo'],0,10))){$pdo->rollBack();json_response(['success'=>false,'message'=>'Assignment date must be inside the inspector enrollment period.'],400);}$member=bbs_inspector_employee($memberId);if(!$member){$pdo->rollBack();json_response(['success'=>false,'message'=>'Team member was not found.'],404);}if(($member['BBSLevel']??'')!=='Operator'||(int)$member['DepartmentID']!==(int)$enrollment['DepartmentID']||(int)$member['SafetyUnitID']!==(int)$enrollment['SafetyUnitID']){$pdo->rollBack();json_response(['success'=>false,'message'=>'Only Operators in the appointed Department and Safety Unit can be added.'],400);}$owned=db_row("SELECT id,SupervisorEmployeeID FROM BBS_Hierarchy_Assignments WHERE MemberEmployeeID=? AND IsActive=1 AND EffectiveFrom<=? AND COALESCE(EffectiveTo,'9999-12-31')>=? LIMIT 1 FOR UPDATE",[$memberId,$asOf,$asOf]);if($owned){$pdo->rollBack();json_response(['success'=>false,'code'=>'MEMBER_ALREADY_ASSIGNED','message'=>(string)$owned['SupervisorEmployeeID']===(string)$enrollment['InspectorEmployeeID']?'This employee is already in this team.':'This employee already belongs to another primary inspector. Admin must transfer the assignment.'],409);}$stmt=$pdo->prepare('INSERT INTO BBS_Hierarchy_Assignments(SupervisorEmployeeID,MemberEmployeeID,DepartmentID,SafetyUnitID,AssignmentType,EffectiveFrom,EffectiveTo,IsActive,Reason,CreatedBy,UpdatedBy) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$reason=bbs_inspector_clean($body['reason']??'')?:'Inspector team assignment';$stmt->execute([$enrollment['InspectorEmployeeID'],$memberId,$enrollment['DepartmentID'],$enrollment['SafetyUnitID'],'permanent',$asOf,$enrollment['EffectiveTo']?:null,1,$reason,$actor,$actor]);$assignmentId=(int)$pdo->lastInsertId();db_execute('INSERT INTO BBS_Inspector_Team_Events(EnrollmentID,AssignmentID,InspectorEmployeeID,MemberEmployeeID,EventType,ActorEmployeeID,ActorMode,Reason) VALUES(?,?,?,?,?,?,?,?)',[$id,$assignmentId,$enrollment['InspectorEmployeeID'],$memberId,'Added',$actor,$access['actorMode'],$reason]);$pdo->commit();bbs_phase1_audit($user,'BBS_INSPECTOR_TEAM_ADD','BBS_Hierarchy_Assignment',(string)$assignmentId,'enrollment='.$id.'; '.$enrollment['InspectorEmployeeID'].' -> '.$memberId);json_response(['success'=>true,'data'=>['assignmentId'=>$assignmentId],'message'=>'Employee added to the inspector team.'],201);}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}}
    $remove=route_params($path,'/bbs/inspectors/:id/team/:assignmentId');if($method==='DELETE'&&$remove!==null){$id=bbs_phase1_positive_int($remove['id']);$assignmentId=bbs_phase1_positive_int($remove['assignmentId']);if(!$id||!$assignmentId)json_response(['success'=>false,'message'=>'Valid enrollment and assignment IDs are required.'],400);$pdo=db();$pdo->beginTransaction();try{$enrollment=bbs_inspector_enrollment($id,true);if(!$enrollment){$pdo->rollBack();json_response(['success'=>false,'message'=>'Inspector enrollment was not found.'],404);}$access=bbs_inspector_access($user,$enrollment,bbs_inspector_today());if(isset($access['error'])){$pdo->rollBack();json_response(['success'=>false,'message'=>$access['error'][1]],$access['error'][0]);}$assignment=db_row('SELECT * FROM BBS_Hierarchy_Assignments WHERE id=? AND SupervisorEmployeeID=? AND DepartmentID=? AND SafetyUnitID=? AND IsActive=1 LIMIT 1 FOR UPDATE',[$assignmentId,$enrollment['InspectorEmployeeID'],$enrollment['DepartmentID'],$enrollment['SafetyUnitID']]);if(!$assignment){$pdo->rollBack();json_response(['success'=>false,'message'=>'Active team assignment was not found in this inspector scope.'],404);}$reason='Removed from inspector team';db_execute('UPDATE BBS_Hierarchy_Assignments SET IsActive=0,Reason=?,UpdatedBy=? WHERE id=?',[$reason,$actor,$assignmentId]);db_execute('INSERT INTO BBS_Inspector_Team_Events(EnrollmentID,AssignmentID,InspectorEmployeeID,MemberEmployeeID,EventType,ActorEmployeeID,ActorMode,Reason) VALUES(?,?,?,?,?,?,?,?)',[$id,$assignmentId,$enrollment['InspectorEmployeeID'],$assignment['MemberEmployeeID'],'Removed',$actor,$access['actorMode'],$reason]);$pdo->commit();bbs_phase1_audit($user,'BBS_INSPECTOR_TEAM_REMOVE','BBS_Hierarchy_Assignment',(string)$assignmentId,'enrollment='.$id.'; member='.$assignment['MemberEmployeeID']);json_response(['success'=>true,'message'=>'Employee removed from the inspector team.']);}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}}
    return true;
}
